// Wiki articles: characters, people and places in the walkthrough, and what items do.
//
// ORIGINAL text written for this app, from facts in public sources (the Final Fantasy Wiki,
// Gamer Corner's FF6 data) and the app's own walkthrough. No guide or wiki text is copied.
// Pixel Remaster names and facts.
//
// ARTICLES fields: id (slug, used in #/wiki/<kind>/<id>), name, kind (party, npc or place), aka
// (other names the text uses; they're colored and linked too), sum (one spoiler-free sentence,
// shown in the summary popup), facts ([[label, value]], spoiler-free), body (paragraphs, and
// { after: "<chapter slug>", text } blocks that stay folded until you reach that chapter).
// **bold** and *italic* work, as in the walkthrough.
//
// ITEM_NOTES: what an item does, by its name in gear-data.js. Plain-stat gear has none.

export const ARTICLES = [
{ id: "terra", name: "Terra", kind: "party", sum: "A young woman sent into Narshe in Magitek armor, who can use magic without espers and remembers almost nothing.", facts: [["Command", "Magic; Trance from chapter 18"], ["First joins", "Chapter 1"], ["Role", "Mage and swordfighter"]], body: [
    "Terra is the first character you control. She knows magic from the start, something no one else in the world seems able to do, and she learns more spells on her own as she levels up. Her Magic stat is among the best in the party, but she can also wear swords and heavy armor, so she works in either row.",
    "Early on she's your healer: Cure carries most of the first chapters. Give her espers that boost Magic once you have them.",
    { after: "escape-from-narshe", text: "She was under Imperial control when she marched on Narshe; the old man removed the device on her head. She has no memory of her past, and the Empire wants her back." },
    { after: "kohlingen-jidoor-and-zozo", text: "After the battle on the snowfield, Terra transforms and flies off. You'll be without her until you find her in Zozo, and she doesn't rejoin until after Vector. Any gear she was wearing goes with her, so don't count on it." },
    { after: "escape-from-vector", text: "Terra is half esper: her father is the esper Maduin. She rejoins with **Trance**, which turns her into her esper form for a while and makes her attacks and spells much stronger. Save it for bosses. **Lightbringer**, **Ragnarok** (the sword) and the **Minerva Bustier** are among her best gear later." },
    { after: "mobliz", text: "In the World of Ruin she's in Mobliz, caring for the orphans, and won't fight at first. She's optional. Beat Humbaba once, come back later, and she joins for good after the second fight (chapter 33)." },
  ] },
  { id: "locke", name: "Locke", kind: "party", sum: "A treasure hunter (he hates being called a thief) who helps the Returners and rescues Terra from Narshe's guards.", facts: [["Command", "Steal"], ["First joins", "Chapter 2"], ["Role", "Fast physical fighter"]], body: [
    "Locke's **Steal** takes an item from an enemy. Many bosses carry gear you can't get any other way yet, like the Guard Leader's **Mythril Knife**, so steal before you finish a fight. The **Thief's Bracer** raises his success rate, and the **Brigand's Glove** turns Steal into a version that also attacks.",
    "He's quick and wears daggers, many swords and throwing weapons. The **Main Gauche** from Mt. Kolts is a good early pick, and the Boomerang and other throwing weapons let him hit hard from the back row.",
    "He leaves the group at the Returners' Hideout and has his own scenario in South Figaro (chapter 7). Re-equip him first; he starts it with nothing.",
    { after: "kohlingen-jidoor-and-zozo", text: "With Locke in the party, visit Kohlingen to learn about Rachel, the woman he couldn't protect. It explains why he's so set on protecting Terra and Celes." },
    { after: "the-falcon-a-world-to-explore", text: "In the World of Ruin, Locke is optional. He's deep in the **Phoenix Cave** (chapter 43), which needs two full parties and the Royal Letter from Owzer's mansion. He brings the **Phoenix** esper and the **Valiant Knife**, and the cave holds his **Wing Edge**. With him back, he can pick Narshe's locked doors for the **Ragnarok** and the **Cursed Shield**." },
  ] },
  { id: "edgar", name: "Edgar", kind: "party", aka: ["King Edgar"], sum: "The charming young king of Figaro, an engineer who secretly backs the Returners while acting friendly to the Empire.", facts: [["Command", "Tools"], ["First joins", "Chapter 3"], ["Role", "Physical fighter with gadgets"]], body: [
    "**Tools** use machines you buy or find. They don't depend on his stats and rarely miss, so they stay useful all game. He starts with the **Auto Crossbow** (hits every enemy). The **Noiseblaster** confuses, the **Bioblaster** poisons, and the **Drill** ignores defense. Set the clock in Zozo's inn for the **Chainsaw**.",
    "Edgar can use spears and the heaviest armor, so he's tough in the front row. With Edgar leading the party, Figaro Castle's shops are half price.",
    "His twin brother Sabin joins at Mt. Kolts.",
    { after: "nikeah-and-the-crimson-robbers", text: "In the World of Ruin, the bandit leader Gerad is Edgar in disguise. He rejoins in Figaro Castle's basement (chapter 30) and is **required**: the castle has to surface before you can reach Kohlingen. The **Debilitator** is sold at the castle afterwards, and his best tool, the **Air Anchor**, is in the Tower of Fanatics." },
  ] },
  { id: "sabin", name: "Sabin", kind: "party", sum: "Edgar's twin brother, who left the throne to train as a monk under Duncan. The strongest fighter in the early game.", facts: [["Command", "Blitz"], ["First joins", "Chapter 4 (Mt. Kolts)"], ["Role", "Front-row brawler"]], body: [
    "**Blitz** moves are entered as button sequences, like a fighting game; the move list shows each input. He learns new ones by level. **Raging Fist** (←, →, ←) is a big single hit, **Aura Cannon** is great against undead and machines, and **Meteor Strike** (a suplex) works on surprising targets, including the Phantom Train.",
    "Blitzes don't depend on his weapon, so his claws matter mostly for plain Fight. He has the highest HP and strength of the early party; keep him in the front row.",
    "His scenario (chapters 9 to 11) is the longest of the three and introduces Shadow, Cyan and Gau.",
    { after: "albrook-and-tzen", text: "In the World of Ruin, Sabin is holding up a collapsing house in Tzen (chapter 27) and joins once you rescue the child inside. Good late weapons: **Dragon Claws** (dropped by the Angler Whelk) and **Tigerfang** (the cave in the Veldt)." },
    { after: "gathering-your-power", text: "Bring Sabin and Gau to the old man's house on the island north of the Veldt for a scene about Gau's family." },
  ] },
  { id: "celes", name: "Celes", kind: "party", sum: "An Imperial general found chained in South Figaro for questioning the Empire. She was given magic by Imperial science.", facts: [["Command", "Runic"], ["First joins", "Chapter 7 (Locke's scenario)"], ["Role", "Mage and swordfighter"]], body: [
    "**Runic** readies Celes's sword to absorb the next spell cast on the field, from either side, and turns it into MP for her. It's superb against bosses that rely on magic, like the Tunnel Armor and Kefka on the snowfield. It also soaks up your own healing spells, so don't use it when an ally is about to cast Cure. It works with most swords.",
    "Like Terra she knows magic from the start, learns spells as she levels, and can wear swords and heavy armor. She's a strong healer and a solid fighter.",
    "At the opera house she stands in for the star singer, and takes off **all** her gear, relics and esper included, before going on stage. Hand it around for the Ultros fight and re-equip her afterwards.",
    { after: "the-magitek-research-facility", text: "In the research facility, Kefka claims she's been working for the Empire all along, and she stays behind. She's back with the group soon after." },
    { after: "the-solitary-island", text: "Celes is the lead in the World of Ruin and is **required**. She starts alone on the Solitary Island with no gear or esper, so re-equip her for defense. Late picks: **Lightbringer**, **Excalibur**, **Ragnarok** (the sword) and the **Minerva Bustier**." },
  ] },
  { id: "cyan", name: "Cyan", kind: "party", sum: "A loyal, old-fashioned knight of Doma Castle who joins Sabin after the Empire's attack on Doma.", facts: [["Command", "Bushido"], ["First joins", "Chapter 9 (Sabin's scenario)"], ["Role", "Front-row swordsman"]], body: [
    "**Bushido** charges up before it strikes: the stronger the technique, the longer you wait. **Fang** is a quick hit, **Sky** sets a counterattack stance, and later techniques hit several times, drain HP and MP, or kill outright. He learns them by level.",
    "He uses katanas only. Good finds: **Kotetsu** (Mobliz), **Kiku-ichimonji** (Jidoor) and the **Murasame** on the Floating Continent. Fang and other Bushido can't be reflected, which helps against Nelapa.",
    "He's old-fashioned about machines, which is played for laughs.",
    { after: "sabin-shadow-and-the-imperial-camp", text: "Kefka's poisoning of Doma killed Cyan's wife and son and nearly everyone in the castle. Grief follows him through the story." },
    { after: "the-falcon-a-world-to-explore", text: "In the World of Ruin, Cyan is optional. He's at the top of **Mt. Zozo** (chapter 35); buy the Rust Rid in Zozo first. Afterwards, sleep in **Doma Castle** with him in the party (chapter 41): it's an optional dungeon that teaches him **all** his remaining Bushido and gives the **Alexander** esper. Bet the Murasame at the Colosseum for the **Masamune**." },
  ] },
  { id: "shadow", name: "Shadow", kind: "party", sum: "A silent ninja-for-hire with a dog named Interceptor. He works for whoever pays and may walk out at any moment.", facts: [["Command", "Throw"], ["First joins", "Chapter 9 (Sabin's scenario)"], ["Optional?", "Partly; he can be lost for good"]], body: [
    "**Throw** hurls a weapon or ninja item for heavy damage: **Shuriken**, later **Fuma Shuriken** and **Pinwheel**, and the Flame, Water and Lightning **Scrolls** for elemental hits. Thrown items are used up. His dog **Interceptor** sometimes blocks attacks and counters on his own.",
    "He's very quick and evasive. Name him in the South Figaro café in chapter 4; it's your only chance.",
    "Early on he's hired help: he may leave after any battle. You can also hire him at Kohlingen's inn for 3,000 gil in chapter 13, and he travels with you to Thamasa in chapter 22. When he leaves, take back his esper and anything you want first.",
    "Sleeping at an inn with Shadow in the party sometimes shows a dream about his past.",
    { after: "before-the-floating-continent", text: "**Don't lose him.** Shadow joins on the Floating Continent. During the escape at the end, don't jump to the airship until the timer reads **0:05**, or he's gone for good." },
    { after: "the-falcon-a-world-to-explore", text: "If you waited for him, he's hurt in the **cave in the Veldt** (chapter 36). He vanishes again after the rescue; bet the **Ichigeki** at the Colosseum (chapter 37) to recruit him for good. His best weapon, the **Kagenui**, is in the Tower of Fanatics." },
  ] },
  { id: "gau", name: "Gau", kind: "party", sum: "A wild boy raised by monsters on the Veldt. He joins if you feed him Dried Meat and copies monsters' moves.", facts: [["Command", "Rage (and Leap on the Veldt)"], ["First joins", "Chapter 11 (Sabin's scenario)"], ["Role", "Monster-skill copier"]], body: [
    "**Rage** turns Gau into a chosen monster: he takes on its attacks and resistances and fights on his own until the battle ends. You can't control him while raging, but many Rages are strong, and some give him immunities or healing.",
    "He learns Rages only on the Veldt. In a Veldt fight, use **Leap**; he leaves, and after more Veldt fights with three people he comes back knowing the Rages of the monsters from both battles. Only monsters you've already fought anywhere can turn up on the Veldt. The app's Rages page tracks what he knows.",
    "**Missable Rages:** monsters found only in places you can't revisit, such as the Imperial camp (Satellite, Doberman), the Phantom Train (Oversoul), Narshe's light-path room and the mine cart, need to be fought at least once there, or Gau can never learn them.",
    "He fights unarmed (his bare hands are strong) and can wear light gear. The **Snow Scarf** is his best armor later.",
    { after: "the-falcon-a-world-to-explore", text: "In the World of Ruin, Gau is optional. Fight on the Veldt with three or fewer people until he shows up (chapter 36)." },
    { after: "gathering-your-power", text: "Bring Gau and Sabin to the old man's house on the island north of the Veldt for a scene about his father." },
  ] },
  { id: "setzer", name: "Setzer", kind: "party", sum: "A flamboyant gambler who owns the world's only airship, the Blackjack, and plans to kidnap the opera's star singer.", facts: [["Command", "Slot"], ["First joins", "Chapter 14 (the opera house)"], ["Role", "Gambler, ranged fighter"]], body: [
    "**Slot** spins three reels; matching symbols give effects from a group heal to big attacks on every enemy. Results are part luck, and a bad line can occasionally backfire.",
    "His weapons are cards and dice. They work from the back row, and dice deal random damage that ignores his strength, so dice users can stay useful at any level.",
    "Joining him gets you the Blackjack and opens the trip south to the Empire.",
    { after: "the-solitary-island", text: "The Blackjack was lost when the world broke." },
    { after: "kohlingen-and-darill-s-tomb", text: "In the World of Ruin, Setzer is in Kohlingen's inn (chapter 31) and is **required**: he opens Darill's Tomb and gives you the **Falcon**, the new airship. His best weapon, the **Fixed Dice**, is inside Kefka's Tower." },
  ] },
  { id: "mog", name: "Mog", kind: "party", sum: "A talking moogle from Narshe's mines who fights with spears and Dance moves he learns from different kinds of ground.", facts: [["Command", "Dance"], ["First joins", "Chapter 2 (briefly); recruitable in chapter 19"], ["Optional?", "Yes"]], body: [
    "**Dance** picks one of Mog's dances; each one randomly uses one of four effects every turn, and he keeps dancing on his own until the fight ends. A dance that doesn't match the ground can fail.",
    "He learns a dance by fighting with him on a new kind of terrain: plains, forest, desert, town (such as Zozo), mountains, caves, water and snow. Have him fight a battle in the Narshe mines in chapter 2 for his first dance.",
    "**The Gold Hairpin choice (chapter 19):** after chasing Lone Wolf to the Narshe cliffs, you save either Mog or the Gold Hairpin (halves MP costs). If you take the Hairpin, Mog won't be back for a long time, and he can **never** learn his water dance, which needs the Lethe River or the Serpent Trench. The Hairpin turns up elsewhere later, so most players pick Mog.",
    "He uses spears like Edgar. The **Snow Scarf** is his best armor later.",
    { after: "the-falcon-a-world-to-explore", text: "In the World of Ruin, Mog is in the Moogle cave in Narshe's mines (chapter 34); bring three people so he can join. Search the wall behind him for **Molulu's Charm** (no random battles, Mog only), and fight once in the snow for **Snowman Rondo**. Keep him in the party to recruit **Umaro** afterwards." },
  ] },
  { id: "strago", name: "Strago", kind: "party", sum: "An elderly man of Thamasa with his granddaughter Relm. He's a blue mage who learns monsters' special attacks.", facts: [["Command", "Lore"], ["First joins", "Chapter 22 (Thamasa)"], ["Optional?", "Yes, in the World of Ruin"]], body: [
    "**Lore** casts monster skills Strago has learned. He learns one by being in a battle, awake and able to act, when an enemy uses it. Start with **Aqua Breath** (great against the Flame Eater) and pick up **White Wind** from the Venobennu on the espers' mountain.",
    "Strago knows no regular spells when he joins: give him an esper straight away. His Magic is good and his body is frail, so keep him in the back row.",
    "Many Lores come from specific monsters or bosses; the chapter notes list where. Some are missable, so check before leaving a dungeon.",
    { after: "the-falcon-a-world-to-explore", text: "In the World of Ruin, Strago is optional. He's with Kefka's cultists at the foot of the Tower of Fanatics, and only Relm can bring him back (chapter 40). Then take him to Ebot's Rock to learn **Grand Delta** from Hidon. **Force Field** comes only from the Fiend statue in Kefka's Tower. The **Behemoth Suit** is his best armor." },
  ] },
  { id: "relm", name: "Relm", kind: "party", sum: "Strago's bold young granddaughter, a painter whose pictures can come to life. She insists on joining the trip.", facts: [["Command", "Sketch"], ["First joins", "Chapter 23 (the espers' refuge)"], ["Optional?", "Yes, in the World of Ruin"]], body: [
    "**Sketch** paints an enemy and makes the picture use one of its attacks. It can miss, and bosses usually can't be sketched. The **Fake Moustache** (Zone Eater) turns it into **Control**, which lets you choose a monster's moves and targets; that's the best way to make Strago learn Lores.",
    "Relm has the highest base Magic in the game, so she's an excellent caster once she has espers. She wears brushes, rods and costumes; the **Behemoth Suit** is her best armor and the **Magical Brush** and **Rainbow Brush** her best brushes.",
    { after: "the-falcon-a-world-to-explore", text: "In the World of Ruin she's optional. She's with the art collector Owzer in Jidoor (chapter 38); his mansion also has the **Lakshmi** esper and the Royal Letter to the Phoenix Cave. Bring her to the Tower of Fanatics to bring Strago back." },
    { after: "the-veldt-and-gau", text: "If you didn't wait for Shadow on the Floating Continent, Relm is the one you rescue in the cave in the Veldt instead." },
  ] },
  { id: "gogo", name: "Gogo", kind: "party", sum: "A mysterious figure wrapped head to toe, living inside a monster's belly, who has mastered the art of mimicry.", facts: [["Command", "Mimic"], ["First joins", "Chapter 42 (the Zone Eater)"], ["Optional?", "Yes"]], body: [
    "**Mimic** repeats the last action an ally took, at no cost: a spell, a Blitz, a Lore, even an item. Gogo can also have up to **three** other commands, chosen on the status screen from anyone's (Steal, Blitz, Rage, Bushido and so on), including Magic with any spell the party knows.",
    "Gogo can't equip espers, so stats never rise from level-up bonuses. Use Gogo as a flexible support who copies your best move.",
    "To reach Gogo, let a Zone Eater on Triangle Island swallow your whole party, then cross its belly. The trip also gives the **Fake Moustache**, **Genji Armor** and **Magical Brush**.",
  ] },
  { id: "umaro", name: "Umaro", kind: "party", sum: "A huge, shaggy yeti living in a cave beyond the Narshe cliffs. Strong but wild: you can't give him orders.", facts: [["Command", "None (always berserk)"], ["First joins", "Chapter 34 (Narshe)"], ["Optional?", "Yes; needs Mog"]], body: [
    "Umaro acts on his own every turn, like a permanently berserk fighter. He has huge HP, strength and defense, and his bare attack is one of the strongest in the game.",
    "Two relics give him new moves: the **Berserker Ring** (cave in the Veldt) lets him hurl a teammate at the enemy, and the **Blizzard Orb** (Ancient Castle) adds an Ice storm on all enemies.",
    "To recruit him, beat him in his cave and talk to him **with Mog in the party**. Without Mog he won't come.",
  ] },
  { id: "banon", name: "Banon", kind: "party", sum: "The leader of the Returners, the rebels fighting the Empire. He hopes Terra's power can turn the war.", facts: [["Command", "Pray"], ["Joins", "Chapter 5 (temporary guest)"], ["Must survive", "Yes, or it's game over"]], body: [
    "**Pray** heals the whole party for free, as often as you like. It's what makes the Lethe River easy; with Banon praying, it's also a safe place to grind.",
    "Banon must not fall on the Lethe River: if he's knocked out against Ultros, the game ends. He's weak, so let him heal rather than attack.",
    "He travels with Terra and Edgar in their scenario (chapter 8), and on the Narshe snowfield (chapter 12) you have to stop the Imperial soldiers before any reach him.",
  ] },
  { id: "leo", name: "Leo", kind: "party", aka: ["General Leo"], sum: "An Imperial general known for fairness and honor, respected even by his enemies. He escorts the party to Thamasa.", facts: [["Command", "Shock"], ["Playable", "Briefly, at the end of chapter 23"]], body: [
    "Leo isn't a real party member. He travels with Terra and Locke as their escort, and you control him alone for a short scene in Thamasa.",
    "When you play him, he's very strong: **Shock** deals heavy damage, and his normal attacks hit hard. The fights in that scene are short.",
    { after: "before-the-floating-continent", text: "Kefka kills Leo in Thamasa, then takes the espers' magicite. You can't recruit him and don't lose anything by it." },
  ] },
  { id: "biggs", name: "Biggs", kind: "party", sum: "An Imperial soldier piloting Magitek armor in the raid on Narshe, alongside Wedge and the young woman.", facts: [["Command", "Magitek"], ["Playable", "Chapter 1 only"]], body: [
    "Biggs and Wedge are the two soldiers with Terra in the opening. Their Magitek armor's beams and Tek Missile win every fight, so there's nothing to manage.",
    { after: "escape-from-narshe", text: "Both soldiers vanish in the blast when the frozen esper reacts to Terra." },
  ] },
  { id: "wedge", name: "Wedge", kind: "party", sum: "An Imperial soldier piloting Magitek armor in the raid on Narshe. The two of them lead the march on the mines.", facts: [["Command", "Magitek"], ["Playable", "Chapter 1 only"]], body: [
    "Wedge and Biggs are the two soldiers with Terra in the opening. Their Magitek armor makes the raid an easy fight-by-fight walk.",
    { after: "escape-from-narshe", text: "Both soldiers vanish in the blast when the frozen esper reacts to Terra." },
  ] },
{ id: "kefka", name: "Kefka", kind: "npc", sum: "A shrieking, clownish general of the Empire with a taste for cruelty, who shows up wherever the Empire wants something.", facts: [["Met", "Chapter 3, Figaro Castle"], ["Serves", "Emperor Gestahl"]], body: [
    "Kefka is one of the Empire's generals: painted face, gaudy clothes, a high cackle and no conscience at all. He turns up at Figaro Castle demanding Terra, and when Edgar won't hand her over he sets the castle alight without a second thought.",
    { after: "sabin-shadow-and-the-imperial-camp", text: "Outside Doma he goes over General Leo's head and poisons the river that feeds the castle, killing almost everyone inside. Cyan's family are among the dead." },
    { after: "vector-and-the-magitek-factory", text: "After his attack on Narshe fails, he turns up in Vector overseeing the draining of captured espers, and dumps the spent Ifrit and Shiva like rubbish." },
    { after: "the-espers-refuge", text: "Jailed by then for what he did at Doma, he doesn't stay locked up. Kefka reaches the espers' refuge near Thamasa, slaughters the espers there for their magicite and kills General Leo when Leo tries to stop him." },
    { after: "the-floating-continent", text: "On the Floating Continent he turns on Gestahl and kills him, then pushes the three statues of the Warring Triad out of their careful balance. The release of their power tears the world apart." },
    { after: "the-solitary-island", text: "A year later he has taken the statues' power for himself and rules the broken world as a god from a tower built of rubble, burning anyone who defies him with his Light of Judgment. His worshippers gather at the Tower of Fanatics. Beating him at the top of Kefka's Tower is the end of the game." },
  ] },
  { id: "gestahl", name: "Emperor Gestahl", kind: "npc", aka: ["Gestahl", "Emperor"], sum: "Ruler of the Empire, whose Magitek armies are conquering the world with power drawn from captured espers.", facts: [["Rules", "The Empire, from Vector"], ["Met", "Chapter 21, the banquet"]], body: [
    "Gestahl built his empire on magic stolen from espers, fed into Magitek armor and soldiers. You hear about him from the start, but only meet him in person after the espers' rampage through Vector, when he offers the Returners peace, apologizes for Doma and asks Terra and Locke to help him find the espers and make amends.",
    { after: "escape-from-vector", text: "Terra's memories show that Gestahl himself led the raid on the espers' world years ago that carried her off as a baby." },
    { after: "the-espers-refuge", text: "The peace was a trick. His real aim was to find the espers through Thamasa; once Kefka has turned them into magicite, Gestahl uses it to raise the Floating Continent and reach the Warring Triad." },
    { after: "the-floating-continent", text: "He wakes the statues hoping to rule with their power, but Kefka turns on him and kills him there." },
    { after: "owzer-s-mansion-and-relm", text: "A portrait of the Emperor hangs in Owzer's mansion. Examine it twice for the Royal Letter, which marks the Phoenix Cave." },
  ] },
  { id: "cid", name: "Cid", kind: "npc", aka: ["Cid Del Norte Marquez"], sum: "The Empire's chief Magitek scientist, a gentle old man who runs the research facility above Vector's factory.", facts: [["Met", "Chapter 17, Magitek Research Facility"], ["Later", "Solitary Island (chapter 26)"]], body: [
    "Cid's research is what turns captured espers into the Empire's Magitek power, but he's no villain: he is uneasy about where Kefka is taking the work, and he knows Celes well and cares for her. He helps the party get out of the facility on the mine cart.",
    { after: "the-solitary-island", text: "A year later he is the only other person on the Solitary Island with Celes, and he's very sick. He has looked after her since she was a girl, almost like a grandfather. **Whether he lives is up to you:** catch fish in the shallows south of the cabin and feed him only the quick swimmers (average ones are usually fine, slow ones make him worse). Talk to him if no fish turn up, and step onto the world map if you need a break: his health doesn't drop while you're out there." },
    { after: "the-solitary-island", text: "If he recovers, he tells Celes about a raft he has been building. If he dies, Celes finds the raft and a note he left her, after one of the game's best-known scenes. Either way she sails off to look for her friends." },
  ] },
  { id: "owzer", name: "Owzer", kind: "npc", sum: "Jidoor's wealthiest citizen, an art collector and patron of the opera whose mansion is full of paintings.", facts: [["Where", "Owzer's mansion, north end of Jidoor"], ["Met", "Chapter 14"]], body: [
    "Owzer lives at the top of Jidoor, the town of the rich, and backs the opera house to the south. His mansion is where you meet the impresario, who has a letter from Setzer about the kidnapping plot.",
    { after: "owzer-s-mansion-and-relm", text: "In the World of Ruin his newest painting turns out to be possessed by the demon Chadarnook, and Relm, who came to paint for him, is caught up in it. After the fight, the Lakshmi esper sits on the bookcase to the right, and his portrait of Emperor Gestahl hides the Royal Letter (examine it twice)." },
  ] },
  { id: "impresario", name: "Impresario", kind: "npc", sum: "The fussy manager of the opera house near Jidoor, frantic about a threat to his star singer.", facts: [["Where", "Opera House, south of Jidoor"], ["Met", "Chapter 14, Owzer's mansion"]], body: [
    "The impresario runs the opera house and worries about little but the show. Setzer has written that he'll kidnap the leading lady during the performance, and since Celes looks just like her, the impresario agrees to put Celes on stage in her place so the gambler takes the wrong woman.",
    "During the show he's the one you report Ultros's note to, which starts the five-minute race to the rafters.",
  ] },
  { id: "duncan", name: "Duncan", kind: "npc", sum: "A famous martial-arts master who trained Sabin, living in a cabin north of South Figaro.", facts: [["Where", "Duncan's cabin, north of South Figaro"], ["Taught", "Sabin's Blitz techniques"]], body: [
    "Sabin left Figaro's throne behind to study under Duncan, and his Blitzes come from that training. When you reach Duncan's cabin the master is gone, and on Mt. Kolts his own son Vargas, jealous that Duncan favored Sabin, claims to have killed him. The cabin's bed is free to use.",
    { after: "the-falcon-a-world-to-explore", text: "Duncan is alive after all. In the World of Ruin he's in a lone cabin in the forests of the north, near Narshe. Bring **Sabin** there and Duncan teaches him his final Blitz, **Phantom Rush**." },
  ] },
  { id: "darill", name: "Darill", kind: "npc", sum: "Setzer's late friend and rival, a fearless pilot whose airship, the Falcon, rests beneath her tomb.", facts: [["Where", "Darill's Tomb"], ["Gives", "The Falcon"]], body: [
    "In their youth Darill and Setzer raced each other through the skies. She flew the Falcon, the fastest airship there was, until she took it up one last time and never came back. Setzer later found the wreck, rebuilt it, and laid it to rest in her tomb.",
    "With the Blackjack gone, Setzer opens the tomb to take the Falcon out again. He has to be in the party for the tomb to open.",
  ] },
  { id: "arvis", name: "Arvis", kind: "npc", sum: "An old man in Narshe who takes Terra in after the raid and quietly works with the Returners.", facts: [["Met", "Chapter 1, Narshe"], ["Where", "His house in Narshe"]], body: [
    "Arvis is the old man whose house Terra wakes up in after the raid. He sympathizes with the Returners, sends Terra off through the mines when the guards come for her, and calls in Locke to help. His house later becomes a meeting place for the Returners, and there's an Elixir in its clock."
  ] },
  { id: "lone-wolf", name: "Lone Wolf", kind: "npc", sum: "A thief who robs an old man in Narshe and runs off into the mines, taking a Moogle hostage when cornered.", facts: [["Met", "Chapter 19, Narshe"], ["Choice", "Mog or the Gold Hairpin"]], body: [
    "Talk to the old man in southeast Narshe, then catch Lone Wolf at his house and chase him north through the mines to the cliffs. There he's holding Mog, and you can only save one thing: **Mog** or the **Gold Hairpin** (a relic that halves MP costs).",
    "Picking Mog is usually the better deal. He joins on the spot and can learn his water dance on the Lethe River or Serpent Trench. If you take the Hairpin, Mog is gone until the World of Ruin and never learns that dance, and Gold Hairpins turn up later in the game anyway.",
  ] },
  { id: "katarin", name: "Katarin", kind: "npc", sum: "A young woman in Mobliz who helps Terra look after the town's orphans after the world falls.", facts: [["Met", "Chapter 28, Mobliz"], ["With", "Duane"]], body: [
    "When Kefka's light wiped out most of Mobliz, the children were left behind. Katarin and her partner Duane are among the few older survivors, and they look after the orphans alongside Terra.",
    { after: "terra-and-the-children-of-mobliz", text: "On your return she and Terra are missing, hiding in the underground shelter. Katarin is expecting Duane's baby, and her news helps Terra understand what she's fighting for." },
  ] },
  { id: "duane", name: "Duane", kind: "npc", sum: "A young man in Mobliz, Katarin's partner, who helps protect the orphans after the world falls.", facts: [["Met", "Chapter 28, Mobliz"], ["With", "Katarin"]], body: [
    "Duane is one of the few young adults left in Mobliz. With Katarin and Terra, he keeps the town's children fed and safe from the monsters prowling outside.",
    { after: "terra-and-the-children-of-mobliz", text: "When Humbaba comes back, find Duane in the injured lad's house and follow the dog to the shelter where Terra and Katarin are hiding. He and Katarin are about to become parents." },
  ] },
  { id: "lola", name: "Lola", kind: "npc", sum: "A young woman in Maranda who waits for letters from her sweetheart, a soldier far away.", facts: [["Where", "Maranda"], ["Met", "Chapter 15 (optional)"]], body: [
    "Lola's sweetheart is the wounded soldier in Mobliz. If you paid to send his letters (500 gil each, five times, for the **Tintinnabulum**), you've already been carrying their correspondence.",
    { after: "the-falcon-a-world-to-explore", text: "In the World of Ruin letters still reach her, but they don't come from Mobliz any more. Her carrier pigeon flies off toward Zozo." },
    { after: "mt-zozo-and-cyan", text: "Her soldier died when the world fell. The letters were written by **Cyan**, who couldn't bear to let her lose hope. Bring Cyan to Lola in Maranda afterwards to finish their story." },
  ] },
  { id: "rachel", name: "Rachel", kind: "npc", sum: "Locke's lost love from Kohlingen, and the reason he's so protective of the people he travels with.", facts: [["Where", "Kohlingen"], ["Seen", "Chapter 13, with Locke in the party"]], body: [
    "Bring Locke to Kohlingen and you learn his past. An accident on one of his treasure-hunting trips left Rachel with no memory of him, and her family sent him away. When the Empire later attacked the town she was killed, remembering Locke only at the very end. An old herbalist in the basement of the northeast house keeps her body preserved, because Locke can't let her go.",
    { after: "the-phoenix-cave-and-locke", text: "This is why Locke went into the Phoenix Cave: the legendary Phoenix esper is said to bring back the dead. Its magicite brings Rachel back for just long enough to thank him and ask him to stop blaming himself. Then the Phoenix stays with Locke." },
  ] },
  { id: "madonna", name: "Madonna", kind: "npc", sum: "A human woman who strays into the espers' hidden world, seen in a vision of the past.", facts: [["Seen", "Chapter 18, Terra's memories"]], body: [
    "In Terra's dream you play the esper Maduin, who finds Madonna collapsed at the gate of the espers' world and brings her to the elder. The espers distrust humans, but Maduin takes her in.",
    { after: "escape-from-vector", text: "Madonna and Maduin fell in love, and their daughter is Terra, half human and half esper. When Gestahl's soldiers forced their way into the espers' world, Madonna was struck down and the baby carried off to the Empire." },
  ] },
  { id: "ultros", name: "Ultros", kind: "npc", sum: "A loud, vain and not very bright purple octopus who keeps ambushing the party at the worst moments.", facts: [["Met", "Chapter 5, Lethe River"]], body: [
    "Ultros talks big, flirts badly and runs away when things go wrong. He first turns up on the Lethe River and attacks the raft; in the struggle Sabin is swept off downriver.",
    { after: "the-opera-house", text: "He comes back to wreck the opera, leaving a note about dropping a huge weight on the stage during Celes's performance, and you have to catch him in the rafters." },
    { after: "the-espers-refuge", text: "He lies in wait on Esper Mountain, where Relm's Sketch makes him flee in a panic." },
    { after: "the-floating-continent", text: "He has one more go on the airship deck on the way to the Floating Continent, this time with his big friend Typhon." },
  ] },
  { id: "siegfried", name: "Siegfried", kind: "npc", sum: "A boastful swordsman who calls himself the world's greatest, and leaps out at you on the Phantom Train.", facts: [["Met", "Chapter 10, Phantom Train"]], body: [
    "Siegfried ambushes the party in the fourth car of the Phantom Train with a lot of bragging, but he's all talk. He grabs the treasure from the chest there and makes off with it.",
  ] },
  { id: "returners", name: "The Returners", kind: "npc", aka: ["Returners"], sum: "The rebel movement fighting the Empire, led by Banon from a hideout in the mountains.", facts: [["Leader", "Banon"], ["Base", "Returners' Hideout, north of Mt. Kolts"], ["Met", "Chapter 5"]], body: [
    "The Returners resist the Empire in secret. Locke scouts for them, King Edgar of Figaro is a hidden ally, and in Narshe the old man Arvis helps them. They hope Terra's power can turn the war, and Banon asks her to become their hope.",
    { after: "the-banquet", text: "After the espers rampage through Vector, the Empire asks for peace and the Returners go to Gestahl's banquet to talk terms." },
    { after: "the-solitary-island", text: "The end of the world scatters them. Most of the World of Ruin is spent finding the old members again." },
  ] },
  { id: "empire", name: "The Empire", kind: "npc", aka: ["Empire"], sum: "Emperor Gestahl's military power, conquering the world with Magitek armor powered by magic taken from espers.", facts: [["Ruler", "Emperor Gestahl"], ["Capital", "Vector, on the southern continent"]], body: [
    "A thousand years after the War of the Magi, the Empire has rediscovered magic by capturing espers and draining them. Its Magitek armor and soldiers have overrun much of the world, and Kefka is one of its generals. When the game opens, it's after the frozen esper in Narshe.",
    "Terra was one of its soldiers, made to obey by a device on her head, until the raid on Narshe.",
    { after: "the-banquet", text: "The espers' attack on Vector breaks its strength, and Gestahl calls for peace." },
    { after: "the-floating-continent", text: "When Kefka kills Gestahl and the world falls, the Empire goes with it. In the World of Ruin, Kefka and his cult are all that remain of it." },
  ] },
  { id: "crimson-robbers", name: "Crimson Robbers", kind: "npc", sum: "A band of thieves in the World of Ruin, planning to loot Figaro Castle while it's stuck under the sand.", facts: [["Met", "Chapter 29, Nikeah"], ["Leader", "Gerad"]], body: [
    "You find the gang in Nikeah's café, boasting about the treasure in the trapped castle. They know a back way in, through the old cave southwest of South Figaro, and following them leads you to the castle's prison.",
    { after: "figaro-castle-s-basement", text: "Their leader was using them as much as they were using him: he needed their secret route to get into his own castle." },
  ] },
  { id: "gerad", name: "Gerad", kind: "npc", sum: "The swaggering leader of the Crimson Robbers, who looks strangely familiar.", facts: [["Met", "Chapter 29, Nikeah"]], body: [
    "Gerad leads the Crimson Robbers and keeps pretending not to know you. Follow him around Nikeah and onto the ship to South Figaro, then into the cave toward Figaro Castle.",
    { after: "figaro-castle-s-basement", text: "Gerad is **Edgar** in disguise. He joined the thieves because they knew a way into the sunken castle, and he rejoins you in the engine room." },
  ] },
  { id: "moogles", name: "The Moogles of Narshe", kind: "npc", aka: ["Moogles"], sum: "A band of talking moogles living in the mines of Narshe, led by Mog.", facts: [["Where", "The Moogle cave, Narshe mines"], ["Met", "Chapter 2"]], body: [
    "When Narshe's guards chase Terra into the mines, Mog and his friends come out to help Locke protect her, and you command them as extra parties. Give Mog a fight so he learns his first dance. Their cave lies north of where Terra fell.",
    { after: "the-airship-and-narshe", text: "Mog can join you for good after the Lone Wolf chase in Narshe, if you choose him over the Gold Hairpin." },
    { after: "narshe-mog-and-the-yeti", text: "In the World of Ruin, Mog waits alone in the Moogle cave. Bring three people so he can join, and search the wall behind him for Molulu's Charm." },
  ] },
  { id: "warring-triad", name: "Warring Triad", kind: "npc", aka: ["Triad"], sum: "Three ancient statues of godlike power, the Goddess, the Fiend and the Demon, at the root of the War of the Magi.", facts: [["Where", "The Floating Continent"]], body: [
    "Legend says three gods once fought a war that nearly ended the world, and that their power gave rise to the espers and to magic itself. They turned themselves to stone, and the three statues were left in balance with each other, holding their power in check. Gestahl and Kefka raise the Floating Continent to reach them.",
    { after: "the-floating-continent", text: "Kefka shifts the statues out of their balance, and the burst of their power breaks the world apart." },
    { after: "kefka-s-tower", text: "Kefka draws on their power from his tower, where you fight the three statues themselves: the Fiend, the Goddess and the Demon." },
  ] },
  { id: "cult-of-kefka", name: "Cult of Kefka", kind: "npc", sum: "Kefka's worshippers in the World of Ruin, who chant at the tower they built for their new god.", facts: [["Where", "Tower of Fanatics"], ["Seen", "Chapter 29 onward"]], body: [
    "After the world falls, some survivors start worshipping the one who broke it. They built the Tower of Fanatics and walk in circles at its foot, chanting. Inside the tower only magic works.",
    { after: "strago-lores-and-ebot-s-rock", text: "Strago has joined them, lost in grief. Only Relm can bring him back to himself." },
  ] },
{ id: "narshe", name: "Narshe", kind: "place", aka: ["Narshe Mines"], sum: "A cold, independent mining town in the far north, built over a maze of mines. The story starts here.", facts: [["World", "Both"], ["Shops", "Weapons, armor, items, relics"], ["Inn", "Yes (free bed in the weapon shop's back room)"], ["Chapters", "1, 2, 8, 12, 19, 34"]], body: [
    "A snowy mining town that keeps out of the Empire's business, at least until Imperial soldiers come for the frozen esper dug out of its mines. Tunnels run under and around the whole town: the west mine leads out toward the Lethe River side, a secret entrance sits in the wall west of the town gate, and the northern mines climb up to the Narshe Cliffs.",
    "The **classroom** south of the entrance has tutorial notes and a free recovery spring. Several clocks hide Elixirs (near the old man's door, and in Arvis's and the elder's houses). After the battle on the snowfield, the house south of where Terra woke lets you take its whole stash: 5,000 gil, an Earring, a Thief's Knife, a Reflect Ring, a Thief's Bracer and a Hyper Wrist.",
    "**Wait on two west mine chests:** a Phoenix Down and a Sleeping Bag there turn into a Guard Bracelet and an Elixir if you leave them for later. When you return with the airship, the thief Lone Wolf leads to a choice between **Mog** and a Gold Hairpin; taking the Hairpin keeps Mog away for a long time.",
    "The shops grow as the story goes on: the Mythril Shield, Silk Robes and Moonring Blade after the snowfield battle, then the Hawkeye, Power Sash, Tiara and Golden Shield once you have the Blackjack.",
    { after: "the-solitary-island", text: "In the World of Ruin, Narshe is nearly deserted and monsters roam its streets. Mog waits in the **Moogle cave**, and beyond the Narshe Cliffs lies Umaro's Cave. If you bring **Locke**, he can open the locked doors: the weapon shop's back room offers the Ragnarok (as an esper or a sword), and a house behind the relic shop holds the Cursed Shield." },
  ] },
  { id: "narshe-cliffs", name: "Narshe Cliffs", kind: "place", aka: ["Narshe Snowfield", "Snowfield"], sum: "The snowy heights above Narshe's mines, where the frozen esper sits on its ledge.", facts: [["World", "Both"], ["Chapters", "12, 19, 34"]], body: [
    "The cliffs north of Narshe, reached through the mines. This is where the frozen esper rests, and where the Returners make their stand when the Empire marches on the town. Before that battle you can swap characters and re-equip everyone on the cliff path.",
    "On the airship trip back to Narshe, the chase after Lone Wolf ends on these cliffs, with the choice between Mog and the Gold Hairpin.",
    { after: "the-solitary-island", text: "In the World of Ruin, a snowy maze leads up to the cliff edge, with a save point at its north end. The frozen esper itself fights you here as [[Valigarmanda]], and beating it opens the way down to Umaro's Cave. The fast blue dragon in the snow maze is the [[Ice Dragon]], one of the eight legendary dragons (it drops the Force Shield). Fight once in the snow with Mog for his Snowman Rondo dance." },
  ] },
  { id: "moogle-cave", name: "Moogle Cave", kind: "place", aka: ["Moogle cave"], sum: "A small cave deep in the Narshe mines where the Moogles live, with a chest that rewards patience.", facts: [["World", "Both"], ["Chapters", "2, 8, 34"]], body: [
    "A hidden corner of the Narshe mines, north of the spot where Terra falls during her escape. The Moogles who help Locke protect her come from here.",
    "Its chest holds a Rune Blade now, but a **Ribbon** if you leave it for the World of Ruin. The Ribbon is one of the best relics in the game, so it's worth the wait.",
    { after: "the-solitary-island", text: "In the World of Ruin you reach it through the secret entrance west of Narshe's gate and the old maze. **Mog** waits here and joins on the spot if you have a free slot. Search the wall behind him for **Molulu's Charm** (no random battles; Mog only). Two chests to the southeast hold an Elixir and a Guard Bracelet." },
  ] },
  { id: "umaros-cave", name: "Umaro's Cave", kind: "place", aka: ["Yeti's Cave"], sum: "An icy cave below the Narshe Cliffs, home to a legendary Yeti.", facts: [["World", "World of Ruin"], ["Chapters", "34"]], body: [
    "A cave you drop into from the Narshe Cliffs in the World of Ruin, after beating the frozen esper. Once you jump in there's no save point and no way out until you've finished it, so come prepared.",
    "Almost everything here causes **Imp**, so Ribbons or White Capes help. The west chest is a trap of three [[Tonberry|Tonberries]] guarding a **Minerva Bustier**; Vanish on the party keeps them from hitting you. There's also an X-Ether and a Gauntlet.",
    "The eastern switch on the far bridge drops you into the Yeti's lair. Take the esper from the bone carving, beat the [[Yeti]] for **Midgardsormr**, then talk to him **with Mog in the party** and **Umaro** joins.",
  ] },
  { id: "figaro-castle", name: "Figaro Castle", kind: "place", aka: ["Figaro"], sum: "The desert castle of King Edgar's Figaro, a kingdom friendly with the Empire on the surface. It can burrow under the sand.", facts: [["World", "Both"], ["Shops", "Edgar's tools, items"], ["Inn", "Free (west wing)"], ["Chapters", "3, 13, 30, 45"]], body: [
    "The seat of the kingdom of Figaro, standing alone in the desert south and west of Narshe. Its king, Edgar, keeps up good relations with the Empire while secretly helping the rebels. The whole castle can dive under the sand and travel to the far side of the mountains, which is how you reach the Kohlingen region; ask the old man in the basement.",
    "The shops sell Edgar's tools: the Noiseblaster and Bioblaster at first (you get an Auto Crossbow free, so don't buy one), and the Flash and Drill after the snowfield battle. With **Edgar as party leader**, everything is half price. The inn in the west wing is free.",
    { after: "the-solitary-island", text: "In the World of Ruin the castle is stuck underground, and you get in through a secret path from the cave near South Figaro into its prison. Clearing the engine room ([[Tentacle]]s) brings it back up; the Soul Sabre and the Royal Crown are hidden in the basement, and the shop adds the **Debilitator**." },
    { after: "kohlingen-and-darill-s-tomb", text: "Later, when the castle travels from the Kohlingen side and bumps into something partway, stop and head to the prison: the east cell leads to the Ancient Castle buried under the desert." },
  ] },
  { id: "figaro-cave", name: "Figaro Cave", kind: "place", aka: ["Cave to South Figaro", "Cave To South Figaro", "South Figaro Cave"], sum: "The cave linking the Figaro desert with South Figaro, with a recovery spring at its entrance.", facts: [["World", "Both"], ["Chapters", "4, 7, 29"]], body: [
    "A short cave southeast of Figaro Castle that leads to South Figaro. A recovery spring sits on the first screen. Locke comes back through it at the end of his escape, and fights the [[Tunnel Armor]] inside.",
    "**Choose your chest:** the upper chest holds a Thunder Rod now (it can win the Tunnel Armor fight in one use), but a **Hero's Ring** if you leave it for the World of Ruin. Other chests here change later too.",
    { after: "the-solitary-island", text: "In the World of Ruin the Crimson Robbers lead you through this cave. Almost everything inside causes Confuse, so a Ribbon or Peace Ring helps. At the far end, jumping on the turtle opens a secret path into Figaro Castle's prison." },
  ] },
  { id: "south-figaro", name: "South Figaro", kind: "place", sum: "A wealthy port town south of Figaro Castle, with good shops and a rich man's mansion full of secrets.", facts: [["World", "Both"], ["Shops", "Weapons, armor, items, relics"], ["Inn", "Yes"], ["Chapters", "4, 7, 29"]], body: [
    "A prosperous trading town past the cave from Figaro Castle. Its shops are a big upgrade early on (Great Sword, Kenpo Gi, Heavy Shield, Plumed Hat, Star Pendants and Jeweled Rings). The forests around town pay well in EXP, and the cabin to the north has a free bed.",
    "**Don't miss:** a man in black walks into the café when you first arrive. Talk to him there; it's your only chance to name him.",
    "The rich man's mansion has a secret passage and a basement maze. You can raid part of it early (Hyper Wrist and Hermes Sandals, using the password \"Courage\" with the old man), and Locke's scenario takes you all the way down for Iron Armor, an Earring and a hidden **Ribbon**.",
    { after: "the-solitary-island", text: "In the World of Ruin, ferries run between here and Nikeah. The shops sell the **Diamond Armor** and are the only place in this world to buy several relics, including Hermes Sandals and Amulets. Gerad of the Crimson Robbers stays at the inn." },
  ] },
  { id: "sabins-house", name: "Sabin's House", kind: "place", aka: ["Sabin's Hut", "Sabin's Cabin", "Duncan's cabin"], sum: "A lone cabin at the foot of Mt. Kolts, north of South Figaro, with a free bed.", facts: [["World", "World of Balance"], ["Inn", "Free bed"], ["Chapters", "4"]], body: [
    "A small cabin north of South Figaro, on the way to Mt. Kolts. Edgar's brother Sabin lived here while training under the martial artist Duncan, and the people you meet here point you up the mountain after him.",
    "Its bed is free, which makes it a handy base for grinding in the forests around South Figaro before you climb.",
  ] },
  { id: "mt-kolts", name: "Mt. Kolts", kind: "place", aka: ["Mt. Koltz", "Kolts"], sum: "A rugged mountain north of South Figaro, threaded with caves, on the road to the Returners' Hideout.", facts: [["World", "Both"], ["Chapters", "4, 5"]], body: [
    "The mountain between South Figaro and the Returners' Hideout. You climb it west to east, ducking in and out of caves; the way on is northwest of the big central cave. A save point waits before the long bridge, and the boss, [[Vargas|Vargas (boss)]], is just past it.",
    "In the central cave, go south around the plateau for the **Main Gauche** (Locke) and follow the wall to a hidden path northeast for the **Gigas Glove**. Star Pendants and Jeweled Rings from South Figaro guard against the Poison and Petrify here.",
  ] },
  { id: "returners-hideout", name: "Returners' Hideout", kind: "place", aka: ["Returner Hideout", "Returners Hideout"], sum: "The secret base of the Returners, the rebels led by Banon, tucked into the mountains north of Mt. Kolts.", facts: [["World", "Both"], ["Chapters", "5"]], body: [
    "The rebels' headquarters, reached by the strip of land north of Mt. Kolts. Here Banon asks Terra to be the rebels' hope, and the river behind the base is your way out when the Empire strikes.",
    "**Genji Glove or Gauntlet:** say \"no\" to Banon three times for the Genji Glove, or \"yes\" for the Gauntlet. You can also say no once, talk to the guard in the north cave for the Genji Glove, and still say yes afterwards. The Genji Glove (two weapons) is the better prize.",
    "A hidden path behind the crates in the north leads to a **White Cape**, and the chests also hold an Air Knife and a Knight's Code.",
  ] },
  { id: "lethe-river", name: "Lethe River", kind: "place", aka: ["Lete River"], sum: "A fast river running from the Returners' Hideout toward Narshe, ridden on a raft.", facts: [["World", "World of Balance"], ["Chapters", "5, 8"]], body: [
    "The river behind the Returners' Hideout. You ride it on a raft, choosing routes at the forks; there's no menu on the raft, so equip before you push off. [[Ultros]] waits after the second save point, and Banon must survive the fight.",
    "**Grinding loop:** at the second fork, \"Up\" circles back to the same fork with fights on the way. With Banon praying and auto-battle on, it's an easy place to gain levels. It's also one of the spots where Mog can learn his water dance.",
    "Terra, Edgar and Banon finish the trip in their own scenario, landing near Narshe.",
  ] },
  { id: "imperial-camp", name: "Imperial Camp", kind: "place", sum: "The Empire's siege camp outside Doma Castle, met in Sabin's scenario. You can't come back once you leave.", facts: [["World", "World of Balance"], ["Chapters", "9"]], body: [
    "The Empire's tents and soldiers ringing Doma Castle in the east. Sabin and Shadow scout it, and Kefka is here.",
    "**One visit only, with unique monsters:** the left chest in the tent northwest of the second Kefka meeting is guarded by a [[Satellite]] (prize: Green Beret), and kicking the chest in the east tent brings [[Doberman]]s. Neither appears anywhere else. Also grab the Mythril Glove and the hidden **Barrier Ring** behind the Satellite tent.",
  ] },
  { id: "doma-castle", name: "Doma Castle", kind: "place", aka: ["Doma"], sum: "The castle of the eastern kingdom of Doma, home of the knight Cyan, under Imperial siege when you first see it.", facts: [["World", "Both"], ["Chapters", "9, 24, 41"]], body: [
    "A proud castle on the eastern continent. When Sabin arrives it's holding out against the Imperial army camped outside, with Cyan among its defenders.",
    { after: "sabin-the-phantom-train", text: "Kefka poisoned the river, and nearly everyone in the castle died, including Cyan's family. The castle stands empty after that." },
    { after: "the-banquet", text: "If your banquet answers freed Doma, you can loot it before the Floating Continent: a Remedy in the lower hall, an Ether and an Elixir (alarm clock) in the west sleeping quarters, an X-Potion in Cyan's room, and **Prayer Beads** in the southeast tower." },
    { after: "the-solitary-island", text: "In the World of Ruin, people say demons attack anyone who sleeps here. Bring Cyan and sleep in the east sleeping quarters to enter the **Dreamscape**. Afterwards the **Alexander** magicite sits on the throne. Any treasure you missed earlier is still here." },
  ] },
  { id: "phantom-forest", name: "Phantom Forest", kind: "place", sum: "A misty forest south of Doma where a ghostly train waits at a lonely station.", facts: [["World", "World of Balance"], ["Chapters", "10"]], body: [
    "The forest south of the Imperial camp. A recovery spring sits on the lake screen; go northeast at the crossroads. At its heart is a station where the [[Phantom Train]] stops to carry the dead onward, and the party ends up on board.",
    "Shadow may still leave your party after battles here, until you board the train.",
  ] },
  { id: "baren-falls", name: "Baren Falls", kind: "place", sum: "A huge waterfall beyond the Phantom Forest. The only way down is to jump.", facts: [["World", "World of Balance"], ["Chapters", "11"]], body: [
    "The waterfall you reach after the Phantom Train. Jumping is the only way on: a string of fish fights follows, then the boss [[Rhizopas]], and you wash up on the Veldt.",
  ] },
  { id: "veldt", name: "Veldt", kind: "place", aka: ["The Veldt"], sum: "Wide plains where monsters from all over the world roam, and where a wild child named Gau lives.", facts: [["World", "Both"], ["Chapters", "11, 19, 24, 36, 46"]], body: [
    "Open grassland on the eastern side of the world. Any monster you've fought anywhere can show up here, which makes it Gau's school: in a Veldt battle, use his **Leap**, keep fighting until he comes back, and he learns the Rages of the monsters he met. Battles give gil and AP but **no EXP**, so it's a good place to learn spells without levelling.",
    "To recruit Gau, buy Dried Meat in Mobliz and fight on the Veldt until he shows up after a battle. A rare [[Grenade]] lives only on the forested island west of the Veldt, and [[Bomb]]s there teach Strago Self-Destruct.",
    { after: "the-solitary-island", text: "In the World of Ruin the Veldt has broken into islands. Fight there with three or fewer people and Gau rejoins. The Cave in the Veldt has opened where Crescent Mountain used to be. The island north of the Veldt has the dinosaur forest, the best EXP in the game." },
  ] },
  { id: "cave-in-the-veldt", name: "Cave in the Veldt", kind: "place", aka: ["Cave In The Veldt", "Cave on the Veldt"], sum: "A cave that opens where Crescent Mountain once stood, with someone hurt inside.", facts: [["World", "World of Ruin"], ["Chapters", "36"]], body: [
    "A World of Ruin dungeon on the Veldt's broken islands. Thieves at a campfire near the start have news, and someone you know is injured deep inside.",
    "Take the south tunnel under the stone bridge; a switch by the south door opens the way east. Save past the plateau before the [[Behemoth King]] (two fights back to back; prize: the Behemoth Suit).",
    "**Treasures:** the Berserker Ring (Umaro) by the stone bridge, the Tigerfang (Sabin) behind a [[Death Warden]], and the **Ichigeki** (Shadow) south of the switch. Keep the Ichigeki for the Colosseum.",
  ] },
  { id: "mobliz", name: "Mobliz", kind: "place", sum: "A quiet village east of the Veldt with a post office, and the place to buy Dried Meat for Gau.", facts: [["World", "Both"], ["Shops", "Weapons, armor, items, relics"], ["Inn", "Yes (free bed behind the relic shop)"], ["Chapters", "11, 28, 33"]], body: [
    "A small farming village just east of the Veldt. Its item shop sells the **Dried Meat** you need to recruit Gau, and the other shops have the Magus Hat (Terra and Celes), Kotetsu (Cyan) and Mythril Claws (Sabin). You can sleep free in the back of the relic shop.",
    "**Missable letters:** a wounded soldier here is writing to someone. Read his letter, then pay the post office 500 gil to reply for him, five times in all, resting at the inn in between. The reward is a **Tintinnabulum**. This only works in the World of Balance.",
    { after: "the-solitary-island", text: "In the World of Ruin, Kefka's light has wrecked Mobliz. Only children are left, protected by **Terra**, who won't leave them at first. A child gives you the **Fenrir** esper. Leaving starts the first [[Humbaba]] fight; come back later to finish it and Terra joins for good. Zombie protection helps with the monsters nearby." },
  ] },
  { id: "crescent-mountain", name: "Crescent Mountain", kind: "place", sum: "A mountain south of the Veldt where you find a diving helmet and dive into the Serpent Trench.", facts: [["World", "World of Balance"], ["Chapters", "11"]], body: [
    "A cave in the hills south of the Veldt. The diving helmet is in the southeast. Taking it sends you into the Serpent Trench right away, with no coming back for a while, so finish your Veldt business and shopping in Mobliz first.",
    { after: "the-solitary-island", text: "In the World of Ruin the mountain is gone; the Cave in the Veldt opens in its place." },
  ] },
  { id: "serpent-trench", name: "Serpent Trench", kind: "place", sum: "An undersea trench you cross in a diving helmet, from Crescent Mountain to Nikeah.", facts: [["World", "Both"], ["Chapters", "11, 27, 28, 29"]], body: [
    "An underwater path the party drifts through on the current, surfacing near Nikeah. At both forks, pick **right**: the first leads to an X-Potion, the second to a drained-pool cave with a **Green Beret**. Mog can learn his water dance here.",
    "[[Aspiran]]s counter special attacks with Giga Volt; use plain attacks, or Gau's Belmodar Rage.",
    { after: "the-solitary-island", text: "In the World of Ruin the sea has drained and the trench is dry land, a walking route linking the Tzen area with Mobliz and Nikeah. A chocobo stable northwest of Tzen makes the trip easy." },
  ] },
  { id: "nikeah", name: "Nikeah", kind: "place", sum: "A busy port town with some of the best shops of its time and a ship across the sea.", facts: [["World", "Both"], ["Shops", "Weapons, armor, items, relics"], ["Inn", "Yes"], ["Chapters", "11, 29"]], body: [
    "The harbor where Sabin's scenario ends, and its best shopping stop: Silk Robes, Kenpo Gi, relics such as the Star Pendant, Fairy Ring and White Cape, and Smoke Bombs. An Elixir hides in the inn's clock. The plains around town are a good place to grind before you board the ship.",
    { after: "the-solitary-island", text: "In the World of Ruin, the Crimson Robbers and their leader Gerad hang out in the café. Ferries run to South Figaro. The shops sell Diamond gear, Gaia Gear, the elemental swords and the **Enhancer** (+7 Magic), plus relics like the Gale Hairpin and Prayer Beads." },
  ] },
  { id: "kohlingen", name: "Kohlingen", kind: "place", sum: "A quiet town in the north-west, across the mountains from Figaro, with ties to Locke's past.", facts: [["World", "Both"], ["Shops", "Weapons, armor, items"], ["Inn", "Yes"], ["Chapters", "13, 31"]], body: [
    "A town on the far side of the mountains from Figaro, reached by taking Figaro Castle under the sand. Jidoor is a long walk south down the coast; a chocobo stable past the cabin north of town makes it quicker.",
    "With **Locke** in the party, visit the northeast house's basement and Rachel's house for his backstory. A Green Beret hides behind the statue in the northeast house (enter from the north). The cabin north of town has a **Hero's Ring** in its lower-left pot. Shadow can be hired at the inn for 3,000 gil.",
    "The [[Fossil Dragon]] in the nearby desert is far tougher than anything else around; running is fine.",
    { after: "the-solitary-island", text: "In the World of Ruin, **Setzer** sits in the inn, and he leads you to Darill's Tomb. The shops sell Diamond gear and Setzer's dice and darts. The Colosseum stands north of town." },
  ] },
  { id: "jidoor", name: "Jidoor", kind: "place", sum: "A rich town of art lovers and the well-off, home of the auction house and the collector Owzer.", facts: [["World", "Both"], ["Shops", "Weapons, armor, items, relics; auction house"], ["Inn", "Yes"], ["Chapters", "13, 14, 19, 32, 38"]], body: [
    "A wealthy town in the south-west, far down the coast from Kohlingen. The opera house is to the south, the art collector Owzer lives in the mansion at the north end, and the **Auction House** sells rare items to the highest bidder.",
    "The shops have the Ninja Gear, White Dress, Kiku-ichimonji (Cyan), Kaiser Knuckle (Sabin), Mythril Shield and Earrings. A chocobo stable sits outside town.",
    { after: "the-solitary-island", text: "In the World of Ruin Jidoor barely seems to notice the end of the world. The shops sell the Sniper, Partisan, Crystal Sword, Angel Wings and Protect Ring. Owzer's mansion holds a painting gone very wrong." },
  ] },
  { id: "auction-house", name: "Auction House", kind: "place", aka: ["Jidoor Auction House"], sum: "Jidoor's auction hall, where rare espers and relics come up for sale at random.", facts: [["World", "Both"], ["Chapters", "19, 32"]], body: [
    "The auction house in Jidoor. What's on sale is random each time you walk in, so keep leaving and re-entering until the lot you want appears. Some lots are jokes you can't actually win.",
    "Once you have the airship, it auctions two espers: **Golem** (20,000 gil; Stop, Stamina +2) and **Zona Seeker** (10,000 gil; Magic +2).",
    { after: "the-solitary-island", text: "In the World of Ruin it still offers Golem and Zona Seeker if you missed them, and a **Hero's Ring** for 50,000 gil." },
  ] },
  { id: "owzers-mansion", name: "Owzer's Mansion", kind: "place", aka: ["Owzer's House", "Owzer's mansion"], sum: "The grand house of Jidoor's art collector Owzer, at the north end of town.", facts: [["World", "Both"], ["Chapters", "14, 38"]], body: [
    "The home of Owzer, Jidoor's richest art lover. On your first visit the opera's impresario is here with a letter about the gambler Setzer, and he sends you to the opera house.",
    { after: "the-solitary-island", text: "In the World of Ruin Owzer has a little girl staying with him, and one of his paintings is causing trouble. Light the lamp at the foot of the stairs, then open the southwest painting in the gallery. Inside: the Moogle Suit, the Lich Ring, and the boss [[Chadarnook]] (attack only its demon form). **Relm** joins, the **Lakshmi** esper is on the bookcase, and examining the Emperor Gestahl painting twice gives the **Royal Letter**, which points to the Phoenix Cave." },
  ] },
  { id: "zozo", name: "Zozo", kind: "place", sum: "A rain-soaked slum of thieves and liars north of Jidoor, where almost nobody tells the truth.", facts: [["World", "Both"], ["Chapters", "13, 18, 35"]], body: [
    "A gloomy town in the mountains north of Jidoor, where almost everyone lies. You climb its buildings by stepping out of windows and across to the next roof; the man outside the inn warns you not to jump between buildings, which is the hint that you can.",
    "**Treasures:** the Burning Fist (Sabin), Brigand's Glove, Hermes Sandals and an X-Potion. Set the clock in the inn to **6:10:50** for Edgar's **Chainsaw**. Your first four espers wait at the top.",
    "The [[Hill Gigas]] gives good EXP but can Magnitude 8 the party as it dies. It's a good place for Mog to learn his town dance.",
    { after: "the-solitary-island", text: "In the World of Ruin, find the one honest man (he wanders outside the inn) and buy **Rust Rid** from him for 1,000 gil. Use it on the west door at the top of the café to reach Mt. Zozo." },
  ] },
  { id: "mt-zozo", name: "Mt. Zozo", kind: "place", sum: "The mountains around and above Zozo. Their summit is out of reach for most of the game.", facts: [["World", "Both"], ["Chapters", "13, 35"]], body: [
    "The range north of Jidoor. In the World of Balance you just follow its east side north to the town of Zozo.",
    { after: "the-solitary-island", text: "In the World of Ruin you can climb it through a rusted door in Zozo's café (Rust Rid opens it). **Cyan** is at the top. Treasures include the Red Cap, Ice Shield, **Thunder Shield**, **Aegis Shield** and **Gold Hairpin**. The switch in the west cave releases the [[Storm Dragon]], an optional legendary dragon; save first. Kill [[Mugbear]]s fast, as they steal gil and run." },
  ] },
  { id: "opera-house", name: "Opera House", kind: "place", aka: ["Jidoor Opera House"], sum: "A grand theater south of Jidoor, famous for its star singer.", facts: [["World", "Both"], ["Chapters", "14, 39"]], body: [
    "The theater south of Jidoor. The story brings you here for a performance that Celes has to sing, and for a race against time through the switch room and the rafters while Locke chases [[Ultros]].",
    "Before the show, Celes takes off all her gear (relics and esper too). Hand it to the others and re-equip her afterwards. The extra switches in the upper room set off funny scenes but cost time.",
    { after: "the-solitary-island", text: "In the World of Ruin, the [[Earth Dragon]], one of the eight legendary dragons, has taken the stage. Press the rightmost of the three left-hand switches in the switch room to drop into the fight. Float (Angel Wings) protects against its Quake. It drops the Magus Rod." },
  ] },
  { id: "albrook", name: "Albrook", kind: "place", sum: "An Imperial port town on the southern continent, where the airship first lands.", facts: [["World", "Both"], ["Shops", "Weapons, armor, items, relics"], ["Inn", "Yes"], ["Chapters", "15, 22, 27"]], body: [
    "A harbor town on the Empire's own continent, next to the airship's landing spot. Vector is to the north. The relic shop sells the **Reflect Ring** and **Amulet**, the item shop has Remedies and Teleport Stones, and an Elixir hides in the clock between the café and the relic shop.",
    "The Imperial Base is to the east. Later in the story, Albrook's docks are where a ship sails for Thamasa.",
    { after: "the-solitary-island", text: "In the World of Ruin, Celes's raft washes ashore nearby. The shops now carry the elemental swords (Flametongue, Icebrand, Thunder Blade), Golden gear and the Sprint Shoes. Tzen is a walk to the north." },
  ] },
  { id: "tzen", name: "Tzen", kind: "place", sum: "A town north of Vector, with a man in the woods who sells a healing esper.", facts: [["World", "Both"], ["Shops", "Weapons, armor, items, relics"], ["Inn", "Yes"], ["Chapters", "15, 19, 27"]], body: [
    "A town on the southern continent, past Vector to the north. It sells the Boomerang (Locke, from the back row), **Hermes Sandals**, Amulets and Black Belts. A chocobo stable is in the forest to the east.",
    "Once you have the airship, a man in the woods northeast of Tzen sells the **Seraph** magicite for 3,000 gil.",
    { after: "the-solitary-island", text: "In the World of Ruin a house in Tzen is collapsing, and **Sabin** is holding it up. You have six minutes to find the child inside (wear Petrify protection; good treasure includes the Blood Sword). The Seraph man now sells it for 10 gil. The shops sell elemental swords, Golden gear and the Thief's Bracer." },
  ] },
  { id: "maranda", name: "Maranda", kind: "place", sum: "A town in the far west of the southern continent, under Imperial control, with strong armor for sale.", facts: [["World", "Both"], ["Shops", "Weapons, armor, items"], ["Inn", "Yes"], ["Chapters", "15, 32"]], body: [
    "An out-of-the-way town in the west of the southern continent. It's an optional detour early on, but it sells **Mythril Mail**, a big armor upgrade. A young woman named Lola lives here, waiting on letters. A chocobo stable is to the east.",
    { after: "the-solitary-island", text: "In the World of Ruin the Falcon's first flight lands here. Lola's letters point to Zozo. The shops sell Crystal gear, the Oath Veil and the Magus Robe. The desert south of town is the best place in the game for AP ([[Cactuar]]s)." },
  ] },
  { id: "vector", name: "Vector", kind: "place", aka: ["Imperial Capital"], sum: "The Empire's capital, an industrial city ruled from Emperor Gestahl's palace.", facts: [["World", "World of Balance"], ["Shops", "Weapons, armor"], ["Inn", "Free, but risky"], ["Chapters", "15, 16, 18, 21"]], body: [
    "The heart of the Empire, north of Albrook. Guards in the north of town attack on sight. The free inn may rob you; instead, visit the old lady in the hut to the west, refuse to pledge to the Empire, beat her two guards, and she heals you free from then on.",
    "The Magitek Factory is reached by climbing crates in the southeast and walking the tracks north. The Imperial Palace is at the north end; don't fight the [[Guardian]] at its gate.",
    { after: "the-solitary-island", text: "Vector was wiped out when the world broke. Kefka's Tower now stands on its ruins." },
  ] },
  { id: "magitek-factory", name: "Magitek Factory", kind: "place", sum: "The Empire's factory in Vector, where Magitek armor is built. A maze of belts, pipes and cranes.", facts: [["World", "World of Balance"], ["Chapters", "16"]], body: [
    "The plant behind Vector where the Empire builds its armor. Conveyor belts, pipes and cranes make it a maze. Most monsters here shrug off physical attacks, so use magic and special commands, and kill [[Trapper]]s first (Lv. 5 Death).",
    "**Get the treasure before following Kefka:** you can't come back down. The haul includes the Flametongue, Thunder Blade, Icebrand, Zephyr Cloak, Golden Armor, Golden Helm, Golden Shield and Dragoon Boots.",
    "[[Flan]]s in the room with [[Ifrit]] and [[Shiva]] give big EXP for little HP. Beating the pair earns both as espers.",
  ] },
  { id: "magitek-research-facility", name: "Magitek Research Facility", kind: "place", sum: "Cid's laboratory at the top of the Magitek Factory, where the Empire studies captured espers.", facts: [["World", "World of Balance"], ["Chapters", "17"]], body: [
    "The lab above the factory where the scientist Cid works. A hidden **Stoneblade** lies south of the westernmost glass tube in the first room.",
    "Past the boss at the door, six espers wait: Unicorn, Maduin, Catoblepas, Phantom, Carbuncle and Bismarck. Save before riding Cid's mine cart out: six battles and a boss follow with no rest.",
  ] },
  { id: "imperial-palace", name: "Imperial Palace", kind: "place", aka: ["Gestahl's Palace"], sum: "Emperor Gestahl's palace at the north end of Vector.", facts: [["World", "World of Balance"], ["Chapters", "16, 21"]], body: [
    "The emperor's seat in Vector. At first only its gate matters, guarded by a [[Guardian]] you shouldn't fight.",
    { after: "the-banquet", text: "For the banquet, Gestahl gives you **four minutes** to talk to his soldiers before dinner. Climb the west side entering every door (the toilet and the roof's device room count) and come down the east side; the throne-room soldiers don't count. Beating the attackers in one hit scores more. A high score unlocks the Imperial Base treasure room. Palace treasures: an Alarm Earring and X-Potion behind the lowest west door, and a Gale Hairpin in an east bedroom." },
  ] },
  { id: "imperial-base", name: "Imperial Base", kind: "place", sum: "An Imperial outpost east of Albrook that guards the way to the Sealed Gate.", facts: [["World", "World of Balance"], ["Chapters", "15, 20, 21, 24"]], body: [
    "A military base east of Albrook. At first the soldiers just throw you out. Later the cave to the Sealed Gate is reached by walking through it and crossing the bridge.",
    { after: "the-banquet", text: "**Treasure room:** a high score at the banquet unlocks it. Inside: 41,000 gil, Angel Wings, a Reflect Ring, Hermes Sandals, an Alarm Earring, an Angel Ring, a Flametongue (in the stove), two Elixirs, an X-Potion and an Ether. Empty it before the Floating Continent." },
  ] },
  { id: "cave-to-the-sealed-gate", name: "Cave to the Sealed Gate", kind: "place", aka: ["Cave To The Sealed Gate", "Sealed Cave"], sum: "A volcanic cave behind the Imperial Base, leading to the gate between the human and esper worlds.", facts: [["World", "World of Balance"], ["Chapters", "20"]], body: [
    "The cave past the Imperial Base. **Terra** must be in the party. Almost everything here is undead, so don't use the Assassin's Dagger (its instant kill heals undead). Ice and Holy work well.",
    "On basement 2 the bridges flip between two layouts; stand only on tiles that exist in both. In the lava cavern, press the trap-looking bridge's switch for a **Genji Glove**, and the left switch on the plateau for a save point.",
    "**Treasures:** the **Ultima Weapon** (sword) south and west of the switches near the Elixir chest, plus hidden items under the stair bridge.",
  ] },
  { id: "sealed-gate", name: "Sealed Gate", kind: "place", sum: "The great door that has kept the esper world shut away from humans for a thousand years.", facts: [["World", "World of Balance"], ["Chapters", "18, 20"]], body: [
    "The barrier between the human world and the realm of the espers, at the end of the cave behind the Imperial Base. Terra hopes to open it and ask the espers for help.",
    { after: "the-banquet", text: "Kefka was waiting here. The espers burst through the gate and tore through Vector, which is why the Empire suddenly asked for peace." },
  ] },
  { id: "esper-world", name: "Esper World", kind: "place", aka: ["Land of Espers"], sum: "The hidden home of the espers, sealed away behind the Sealed Gate.", facts: [["World", "World of Balance (flashback)"], ["Chapters", "18"]], body: [
    "The espers' own land, cut off from humans behind the Sealed Gate. You see it only in a flashback.",
    { after: "the-airship-and-narshe", text: "In Terra's memory you play as the esper Maduin: a human woman, Madonna, wanders through the gate. Their daughter is Terra, which is why she can use magic and Trance. Gestahl's raid on this world is how the Empire first captured espers." },
  ] },
  { id: "thamasa", name: "Thamasa", kind: "place", sum: "A quiet village on an island in the east, whose people seem to know more about the espers than they let on.", facts: [["World", "Both"], ["Shops", "Weapons, armor, items, relics"], ["Inn", "Yes"], ["Chapters", "22, 23, 32, 37, 40"]], body: [
    "A remote village reached by ship from Albrook. The old man in the northeast house is Strago, and his granddaughter is Relm. Its shops have the best gear in the World of Balance: Gaia Gear, Mystery Veil, Heavy Lance, rods for Strago and Relm, Tiger Masks, Golden Armor and more.",
    "**Memento Ring:** after first meeting Strago, go back upstairs in his house and search the wall left of the small table. Esper Mountain lies to the west. The [[Chimera]]s in the nearby forests are tough but pay well.",
    { after: "the-espers-refuge", text: "The villagers are descendants of the Magi, and they can all use magic. They hide it to stay safe." },
    { after: "the-solitary-island", text: "In the World of Ruin, Strago's old friend in town sends him after Hidon at Ebot's Rock, north of town. People here also talk about the Colosseum. The shops sell the Fuma Shuriken, Da Vinci Brush and Luminous Robe." },
  ] },
  { id: "esper-mountain", name: "Esper Mountain", kind: "place", aka: ["Espers' Refuge", "Esper Caves"], sum: "A mountain refuge west of Thamasa where the espers are said to have fled.", facts: [["World", "World of Balance"], ["Chapters", "23"]], body: [
    "Caves and slopes west of Thamasa. Take the **Healing Rod** from the first cave, then follow the partly hidden **east** path. [[Ultros]] waits in the statue room.",
    "Past the save point, three dents in the floor drop you below: the top one leads to the **Chocobo Suit** and **Tabby Suit**, the far-right one to an X-Potion, and the bottom-left one onward.",
    "**White Wind** for Strago: find a pair of [[Venobennu]]s on the outdoor slopes and let them act for three turns. [[Adamankary]]s barely take physical damage.",
  ] },
  { id: "floating-continent", name: "Floating Continent", kind: "place", aka: ["Floating Island"], sum: "A landmass raised into the sky, where the three statues of the Warring Triad rest.", facts: [["World", "World of Balance"], ["Chapters", "25"]], body: [
    "A landmass lifted into the sky. You fly in from the Blackjack's controls with exactly **three** people, after six battles and two bosses on deck. Paths appear as you walk toward them, and plateaus act as warps.",
    "**Last chance:** past the north plateau's stairs you're asked whether to return to the airship. Gear up and finish World of Balance side trips first. Battles here give lots of AP.",
    "**Don't leave too early at the end:** when the timer runs during the escape, wait until it reads **0:05** before jumping, or a friend is lost for good. Blue orbs are chests: the Murasame, Sasuke and a Beret.",
    { after: "the-solitary-island", text: "Kefka moved the statues out of balance, and the world was torn apart. The World of Ruin begins a year later." },
  ] },
  { id: "blackjack", name: "Blackjack", kind: "place", aka: ["The Blackjack"], sum: "Setzer's airship, the only one in the world that isn't the Empire's.", facts: [["World", "World of Balance"], ["Inn", "Free bed on board"], ["Chapters", "14 to 25"]], body: [
    "The gambler Setzer's airship, which first flies you to the southern continent. It has a free bed and a shop, and a man below deck can strip gear from party members who stayed behind. Change your party by talking to people on board.",
    "Once Setzer hands it over, you can fly anywhere you like.",
    { after: "the-solitary-island", text: "The Blackjack was destroyed when the world broke." },
  ] },
  { id: "falcon", name: "Falcon", kind: "place", aka: ["The Falcon"], sum: "A swift airship that opens up the World of Ruin to free exploration.", facts: [["World", "World of Ruin"], ["Chapters", "31 to 48"]], body: [
    { after: "kohlingen-and-darill-s-tomb", text: "The airship of Setzer's late friend Darill, raised from Darill's Tomb. With it you can go anywhere, and the rest of the game is yours to order. Its first flight lands at Maranda. An invisible monster, [[Deathgaze]], roams the sky and attacks it at random; beat it for **Bahamut**. To enter the Phoenix Cave, hover over its opening and press the button." },
  ] },
  { id: "solitary-island", name: "Solitary Island", kind: "place", sum: "A tiny island where Celes wakes, a year after everything changed.", facts: [["World", "World of Ruin"], ["Chapters", "26, 32"]], body: [
    "Where the World of Ruin begins: a small island with a cabin, Celes and Cid. Feed Cid fish from the shallows south of the cabin: fast fish are good, slow ones are bad for him. Step outside and save first; his health doesn't drop while you're out.",
    "Celes is alone, so avoid the desert's [[Black Dragon]] (Zombie on her alone means game over).",
    "Come back later for the **Quetzalli** magicite on the beach. Relm can Sketch the [[Land Ray]] or [[Peeper]] here to teach Strago Mighty Guard and White Wind.",
  ] },
  { id: "darills-tomb", name: "Darill's Tomb", kind: "place", aka: ["Daryl's Tomb", "Darill's tomb"], sum: "The resting place of Setzer's old friend Darill, near Kohlingen. Only Setzer can open it.", facts: [["World", "World of Ruin"], ["Chapters", "31"]], body: [
    "A tomb in the World of Ruin, marked by Setzer once he joins in Kohlingen. **Setzer must be in the party.** The puzzles use a turtle and the water level of a central room; the walkthrough lists the order.",
    "Bring **Zombie protection** (Amulets or Ribbons, or Holy Water). **Treasures:** the Genji Helm, Crystal Mail, Regal Gown, Man-Eater, and the **Growth Egg** (double EXP) through a hidden passage in the third floor's east wall. A monster-in-a-box [[Angler Whelk]] guards the Dragon Claws.",
    "The boss, [[Dullahan]], waits at Darill's monument. Afterwards, you get the **Falcon**.",
  ] },
  { id: "colosseum", name: "Colosseum", kind: "place", aka: ["Coliseum", "Dragon's Neck Coliseum", "Dragon's Neck Colosseum", "Dragon's Neck"], sum: "An arena north of Kohlingen where you bet items on fights to win rare prizes.", facts: [["World", "World of Ruin"], ["Chapters", "37, 46"]], body: [
    "An arena built on the Dragon's Neck, north of Kohlingen. In the World of Balance only a cabin stands there (the one with the Hero's Ring in its pot).",
    "You wager an item and pick a fighter; the opponent and prize are shown first. You lose the item win or lose, and your fighter acts alone. **Save before every bet.**",
    "**Worthwhile bets:** the Ragnarok sword for the **Lightbringer**, the Murasame for the **Masamune**, an Elixir for a Rename Card and that for the **Miracle Shoes**. Bet the **Ichigeki** to win back a friend.",
  ] },
  { id: "tower-of-fanatics", name: "Tower of Fanatics", kind: "place", aka: ["Fanatics' Tower", "Cultists' Tower"], sum: "A tall tower in a ring of mountains, built by Kefka's cult. Only magic works inside.", facts: [["World", "World of Ruin"], ["Chapters", "29, 40, 44"]], body: [
    "The cultists' tower stands in a ring of mountains between the old Serpent Trench and Nikeah. Inside, only spells and items work: no Fight, no special commands. You can't Teleport out.",
    "Prepare with **Reflect Rings**, **Float**, Fire protection, high Magic, and someone who knows **Reraise**: the [[Magic Master]] at the top casts Ultima as it dies. Battles give no EXP but lots of AP.",
    "**Treasures:** the Air Anchor (Edgar), Genji Shield, Kagenui (Shadow), Force Armor and, from the boss, the **Soul of Thamasa**. The optional [[Holy Dragon]] roams the 26th floor.",
    { after: "strago-lores-and-ebot-s-rock", text: "Strago wanders entranced at its foot. Bring **Relm** to wake him." },
  ] },
  { id: "ebots-rock", name: "Ebot's Rock", kind: "place", sum: "A cave north of Thamasa where a legendary monster lurks behind a hungry chest.", facts: [["World", "World of Ruin"], ["Chapters", "40"]], body: [
    "A cave on the islands north of Thamasa. **Strago** must be in the party. Floor switches warp you around at random; collect **22 pieces of coral** from chests and feed them all at once to the hungry chest. The game doesn't keep count for you.",
    "The boss is [[Hidon]]. When its Hidonites fall it uses Grand Delta, so keep Strago standing to learn it.",
  ] },
  { id: "dreamscape", name: "Dreamscape", kind: "place", aka: ["Cyan's Dream", "Cyan's Soul"], sum: "A nightmare world inside Cyan's sleeping mind, reached from Doma Castle.", facts: [["World", "World of Ruin"], ["Chapters", "41"]], body: [
    "Sleep in Doma Castle's east quarters with Cyan in the party and you follow his soul into a dream with your other **three** members. It runs through dream versions of earlier places: a dream Phantom Train and dream mines.",
    "Each area can be passed only once. Fight [[Alluring Rider]]s for Strago's Doom and Roulette. On the dream train, look for the Genji Glove, Flame Shield and Ice Shield.",
    "Bosses: [[Curlax]], [[Laragorn]] and [[Moebius]], then [[Wrexsoul]]. Afterwards Cyan learns all his Bushido, and the **Alexander** magicite waits on Doma's throne.",
  ] },
  { id: "triangle-island", name: "Triangle Island", kind: "place", sum: "A small triangular island in the far northeast, home to rare monsters.", facts: [["World", "Both"], ["Chapters", "24, 42"]], body: [
    "A little island in the far northeast. In the World of Balance, the rare [[Intangir]] lives here, mostly in its tiny forest. Meet one, even if you run, so Gau can learn its Rage.",
    { after: "the-solitary-island", text: "In the World of Ruin, the [[Zone Eater]] lives here. Let it **Engulf your whole party** to enter the Zone Eater's Belly, where Gogo waits." },
  ] },
  { id: "zone-eaters-belly", name: "Zone Eater's Belly", kind: "place", aka: ["Zone Eater's belly"], sum: "The inside of a giant monster that swallows people whole. A whole dungeon lives in there.", facts: [["World", "World of Ruin"], ["Chapters", "42"]], body: [
    "Reached by letting a [[Zone Eater]] on Triangle Island swallow your party. The light just north of the start is the way out.",
    "Men in green on the bridges throw you below if they touch you (do it once for the Ether and Red Jacket). The crushing-ceiling room hides the Zephyr Cloak, Hero's Ring and Pinwheel. Also look for the Genji Armor, Magical Brush and **Fake Moustache** (Relm's Sketch becomes Control).",
    "Never Throw at [[Amduscias]] or [[Covert]]. **Gogo** joins in the last room.",
  ] },
  { id: "phoenix-cave", name: "Phoenix Cave", kind: "place", sum: "A cave inside a star-shaped ring of mountains north of Tzen, said to hold a legendary esper.", facts: [["World", "World of Ruin"], ["Chapters", "43"]], body: [
    "Hover the Falcon over the small opening in the star-shaped mountains north of Tzen. You need **two full parties**, switching between them so one holds switches for the other. Teleport doesn't work; the crane at the landing takes you out.",
    "Draining the flooded room in the upper cave cools the lava below. The lava cave has the **Wing Edge** and a **Ribbon**. The optional [[Red Dragon]] guards the Dragon Horn chest. Most monsters here are weak to Ice.",
    { after: "the-phoenix-cave-and-locke", text: "Locke is inside, looking for the esper Phoenix, which can bring back the dead. He joins with **Phoenix** (Reraise) and the Valiant Knife." },
  ] },
  { id: "ancient-castle", name: "Ancient Castle", kind: "place", sum: "A castle from the War of the Magi, buried deep under the desert.", facts: [["World", "World of Ruin"], ["Chapters", "45"]], body: [
    "Reached from Figaro Castle's prison when the castle bumps into something on its way from the Kohlingen side. In the cave, everything has Reflect, so use **physical attacks**. You can't Teleport out.",
    "Examine the **Odin** statue in the throne room for the esper. Then sit on the queen's throne, take five steps down and press the button: a staircase opens in the library, and the queen's statue below turns Odin into **Raiden**. The [[Blue Dragon]] waits in that basement.",
    "**Treasures:** the Blizzard Orb (Umaro), a Gold Hairpin, Wing Edge, Death Tarot, and the Gladius and Master's Scroll from monsters-in-a-box.",
  ] },
  { id: "kefkas-tower", name: "Kefka's Tower", kind: "place", sum: "Kefka's towering stronghold, the last dungeon of the game.", facts: [["World", "World of Ruin"], ["Chapters", "47, 48"]], body: [
    "The final dungeon, raised from the rubble of the world. You storm it with **three parties** at once, up to twelve fighters. You can Teleport out at any time to rearrange.",
    "Start with the third party: park it on the save point before its boss and you can save whenever you like. Two of the legendary dragons, [[Skull Dragon]] and [[Gold Dragon]], are inside, plus a hidden Ribbon, the Fixed Dice and other treasure.",
    "There's no saving once the final climb starts, so use your Elixirs and Megalixirs freely.",
    { after: "the-solitary-island", text: "The tower stands on the ruins of Vector." },
  ] },
  { id: "house-near-the-imperial-camp", name: "House near the Imperial Camp", kind: "place", sum: "A lone house where Sabin meets Shadow, with a traveling merchant outside.", facts: [["World", "Both"], ["Chapters", "9, 46"]], body: [
    "The house east of where Sabin washes up, on the way to the Imperial Camp. Shadow is here and offers to join. A merchant outside sells Shuriken for Shadow's Throw, plus Sprint Shoes and ninja scrolls.",
    { after: "gathering-your-power", text: "This is the home of Gau's father. In the World of Ruin it stands on the island north of the Veldt; bring **Sabin and Gau** for a touching scene." },
  ] },
  { id: "dinosaur-forest", name: "Dinosaur Forest", kind: "place", aka: ["Dinosaur forest"], sum: "A forest on the island north of the Veldt where giant dinosaurs roam. The best EXP in the game.", facts: [["World", "World of Ruin"], ["Chapters", "46"]], body: [
    "A forest on the island north of the Veldt in the World of Ruin. [[Tyrannosaur]]s (weak to Ice) give the most EXP in the game but use Meteor, and pairs of them are pincer attacks you can't escape. The rare [[Brachiosaur]] casts Ultima but can drop a Celestriad.",
    "Only go when you're strong, and wear the Growth Egg for double EXP.",
  ] }
];

